import {inject, Injectable} from '@angular/core';
import {Apollo} from 'apollo-angular';
import {catchError, map, Observable, throwError} from 'rxjs';
import {PokemonEvolutionChain} from '../models/pokemon.model';
import {HttpErrorResponse} from '@angular/common/http';
import {GET_POKEMON_EVOLUTIONS} from '../graphql/pokemon.queries';

@Injectable({
  providedIn: 'root'
})
export class PokemonGraphqlService {

  private apollo = inject(Apollo);


  getPokemonEvolutions(pokemonId: number): Observable<PokemonEvolutionChain |null> {
    return this.apollo.watchQuery<{ pokemon_v2_evolutionchain: PokemonEvolutionChain[] }>({
      query: GET_POKEMON_EVOLUTIONS,
      variables: {pokemonId}
    }).valueChanges.pipe(
      map(
        (result) =>
          result.data?.pokemon_v2_evolutionchain?.length ? result.data.pokemon_v2_evolutionchain[0] : null),
      catchError(this.handleError)
    );

  }


  private handleError(err: HttpErrorResponse): Observable<never> {
    return throwError(() => err);
  }


}

import {inject, Injectable} from '@angular/core';
import {HttpClient, HttpErrorResponse} from '@angular/common/http';
import {catchError, map, Observable, switchMap, throwError} from 'rxjs';
import {Pokemon, PokemonDetails, PokemonSpecies} from '../models/pokemon.model';
import {environment} from '../../../environments/environment';

@Injectable({
  providedIn: 'root'
})
export class PokemonService {

  private http: HttpClient = inject(HttpClient)

  getPokemon(idOrName: string | number): Observable<PokemonDetails> {
    return this.http.get<Pokemon>(`${environment.BASE_URL}/pokemon/${idOrName}`).pipe(
      switchMap(
        pokemon => this.http.get<PokemonSpecies>(`${environment.BASE_URL}/pokemon-species/${pokemon.id}`).pipe(
          map((pokemonSpecies)=>({
            pokemon,
            pokemonSpecies
          }))
        )
      ),
      catchError(this.handleError)
    );
  }


  private handleError(err: HttpErrorResponse): Observable<never> {
    return throwError(() => err);
  }
}

