import {Component, inject} from '@angular/core';
import {FormControl, ReactiveFormsModule} from '@angular/forms';
import {Router} from '@angular/router';

@Component({
  selector: 'app-search-page',
  standalone: true,
  imports: [
    ReactiveFormsModule
  ],
  templateUrl: './search-page.component.html',
  styleUrl: './search-page.component.css'
})
export class SearchPageComponent {

  searchControl: FormControl = new FormControl();

  private router: Router = inject(Router);

  searchByQuery() {
    const query: string | number = this.searchControl.value;
    this.search(query)
  }

  randomSearch() {
    const randomId = Math.floor(Math.random() * 898) + 1;
    this.search(randomId)
  }

  search(query: string | number) {
    if (query) {
      this.router.navigate(['pokemon', query]);
    }
  }

}

import {Component, Input} from '@angular/core';
import {Pokemon} from '../../../../core/models/pokemon.model';
import {NgForOf} from '@angular/common';

@Component({
  selector: 'app-stats',
  standalone: true,
  imports: [
    NgForOf
  ],
  templateUrl: './stats.component.html',
  styleUrl: './stats.component.css'
})
export class StatsComponent {

  @Input()
  pokemon! : Pokemon

  formatStatName(statName: string): string {
    const statNameMap: { [key: string]: string } = {
      'hp': 'HP',
      'attack': 'ATK',
      'defense': 'DEF',
      'special-attack': 'SATK',
      'special-defense': 'SDEF',
      'speed': 'SPD'
    };

    return statNameMap[statName] || statName.toUpperCase();
  }

}

